var BANK={
  1:['light','wind','leaf','moon','sky','rain','snow','stone','wave','star','tree','frog','path','mist','dusk','calm','bee','seed','cloud','ice','sun','sand','book','door','fish','bird','hand','fire','rose','air','sea','hill','lake','bell','song','dream','night'],
