  3:['butterfly','horizon','afternoon','harmony','infinity','remember','september','chocolate','dinosaur','aquarium','mysterious','photography']
};
function pick(arr,rnd){ return arr[Math.floor(rnd()*arr.length)]; }
function sylOf(w){ return BANK[1].indexOf(w)>=0?1:(BANK[2].indexOf(w)>=0?2:3); }
function line(target,rnd){
  var words=[]; var sum=0; var guard=0;
  while(sum<target && guard<200){
    var maxSyl=target-sum; var pool=[];
    for(var s=1;s<=Math.min(3,maxSyl);s++) pool=pool.concat(BANK[s]);
    var w=pick(pool,rnd); words.push(w); sum+=sylOf(w); guard++;
  }
  return {words:words, syllables:sum};
}
function generate(seed){
  var rnd=(function(s){ s=(s||12345)>>>0; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; })(seed);
  var l1=line(5,rnd), l2=line(7,rnd), l3=line(5,rnd);
  return {lines:[l1.words.join(' '), l2.words.join(' '), l3.words.join(' ')], syllables:[l1.syllables,l2.syllables,l3.syllables]};
}
var EXPORTS={generate:generate, BANK:BANK};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HaikuForgePure = EXPORTS; }
